def find_lucky_time(x, hh, mm):
    hours, minutes = hh, mm
    while True:
        new_hours, new_minutes = (hours - x // 60, minutes - x % 60)
        if 0 <= new_hours <= 23 and 0 <= new_minutes <= 59 and '7' in str(new_hours) or '7' in str(new_minutes):
            return (x // 60) + (x % 60) // 5
        hours, minutes = new_hours, new_minutes

x, hh, mm = map(int, input().split())
