def count_sofas(sofas, x1, y1, x2, y2, cnt_l, cnt_r, cnt_t, cnt_b):
    left, right, top, bottom = 0, 0, 0, 0

    for sofa in sofas:
        sx1, sy1, sx2, sy2 = sofa

        if (sx1 < x1 < sx2) and (sy1 == y1 or sy2 == y1):
            left += 1
        elif (sx2 < x1 < sx1) and (sy1 == y1 or sy2 == y1):
            right += 1
        elif (sy1 < y1 < sy2) and (sx1 == x1 or sx2 == x1):
            top += 1
        elif (sy2 < y1 < sy1) and (sx1 == x1 or sx2 == x1):
            bottom += 1

    return left, right, top, bottom

def find_sofa(sofas, cnt_l, cnt_r, cnt_t, cnt_b):
    for i, sofa in enumerate(sofas, start=1):
