import java.util.Scanner;

public class Polycarp {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();
        for (int t = 1; t <= T; t++) {
            int n = scanner.nextInt();
            int[] plays = new int[n];
            int[] clears = new int[n];
            for (int i = 0; i < n; i++) {
                plays[i] = scanner.nextInt();
                clears[i] = scanner.nextInt();
            }
            boolean correct = true;
            for (int i = 0; i < n; i++) {
                if (plays[i] != polycarp(plays, clears, i)) {
                    correct = false;
                    break;
                }
            }
            if (correct) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }
    static int polycarp(int[] plays, int[] clears, int moment) {
        int maxPlays = 0;
        int maxClears = 0;
        for (int i = 0; i < moment; i++) {
            if (plays[i] > maxPlays) {
                maxPlays = plays[i];
            }
            if (clears[i] > maxClears) {
                maxClears = clears[i];
            }
        }
        return maxPlays + maxClears;
    }
}

