def find_sequence(n, k):
    if k > n or k * (k + 1) // 2 > n:
        return -1

    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)

    max_gcd = 1
    for factor in factors:
        count = k // factor
        if count > 0:
            max_gcd = max(max_gcd, factor)
            if k == count * factor:
                return [factor] * count
            else:
                remaining = n - count * factor
                result = [factor] * count
                result.extend(find_sequence(remaining, k - count))
                if result:
                    return result

    return [max_gcd] * k

