def find_sequence(n, k):
    if n == 1 and k > 1:
        return "No"
    if n == 0 and k > 0:
        return "No"
    if n < 0 or k < 0:
        return "No"
    if n == 1 and k == 1:
        return "Yes\n-1"
    sequence = []
    while n > 0 and k > 0:
        if n % 2 == 1:
            sequence.append(k-1)
            n -= 2**(k-1)
        k -= 1
    if n == 0:
        sequence.sort(reverse=True)
        return "Yes\n" + " ".join(map(str, sequence))
    else:
        return "No"

