import sys

n, k = map(int, sys.stdin.readline().split())
a = list(map(int, sys.stdin.readline().split()))

def is_valid(x, y):
    if x + y == 0:
        return True
    if x + y == n:
        return True
    if x + y == 1:
        return a[x] % k == 0
    if x + y == n - 1:
        return a[y] % k == 0
    if x + y == n - 2:
        return a[x] % k == 0 and a[y] % k == 0
    return a[x] % k == 0 and a[y] % k == 0 and a[x + y - 1] % k == 0


def count_ways(x, y):
    if x + y == 0:
        return 1
    if x + y == n:
        return 1
    if x + y == 1:
        return 1 if a[x] % k == 0 else 0
    if x + y == n - 1:
        return 1 if a[y] % k == 0 else 0
    if x + y == n - 2:
        return 1 if a[x] % k == 0 and a[y] % k == 0 else 0
    return (
        count_ways(x - 1, y)
        + count_ways(x - 1, y - 1)
        + count_ways(x, y - 1)
        + count_ways(x - 1, y - 2)
    )


print(count_ways(n - 1, 0))

