from math import gcd

def is_valid(deck, k):
    product = 1
    for card in deck:
        product *= card
    return product % k == 0

def count_valid_decks(n, k, cards):
    count = 0
    for x in range(n):
        for y in range(n - x):
            if x + y < n:
                deck = cards[x:n-y]
                if is_valid(deck, k):
                    count += 1
    return count

# Read input
