def manhattan_distance(x, y, a, b):
    return abs(x - a) + abs(y - b)

def min_ops_to_reach(seq, x, y):
    dx, dy = x, y
    steps = 0
    for op in seq:
        if op == "U":
            dy += 1
        elif op == "D":
            dy -= 1
        elif op == "L":
            dx -= 1
        elif op == "R":
            dx += 1
        steps += 1
        if dx == x and dy == y:
            break
    return steps if (dx == x and dy == y) else -1

n = int(input())
seq = input()
x, y = map(int, input().split())

min_steps = min_ops_to_reach(seq, x, y)
if min_steps == -1:
    print(-1)
else:
    current_pos = [0, 0]
    current_seq = ""
    min_len = 0
    i = 0
    while current_pos[0] != x or current_pos[1] != y:
        next_pos = [current_pos[0], current_pos[1]]
        if seq[i] == "U":
            next_pos[1] += 1
        elif seq[i] == "D":
            next_pos[1] -= 1
        elif seq[i] == "L":
            next_pos[0] -= 1
        elif seq[i] == "R":
            next_pos[0] += 1
        steps = manhattan_distance(next_pos[0], next_pos[1], x, y)
        if steps < min_len or (steps == min_len and i < min_len - 1):
            min_len = steps
            min_seq = seq[:i] + seq[i+1:]
    print(min_len)

