    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def find_primes(n):
    # Check if n is a prime
    if is_prime(n):
        return [n]

    # Start from the smallest prime greater than n // 2
    for p in range(int(n / 2) + 1, n, -1):
        if is_prime(p):
            # Try to find another prime less than p
            for q in range(2, p):
                if is_prime(q):
                    r = n - p - q
                    if is_prime(r):
                        return [p, q, r]
                    elif r == 0:
                        return [p, q]

    raise ValueError("No solution found")

