def is_in_pocket(n, m, x, y, vx, vy):
    pockets = [(0, 0), (n-1, 0), (n-1, m-1), (0, m-1)]
    dx, dy = abs(vx), abs(vy)

    while True:
        x += vx
        y += vy
        if (x, y) in pockets:
            return pockets.index((x, y))
        if not (0 <= x < n and 0 <= y < m):
            return -1
        if not dx or not dy:
            if x % 2 == 0 and y % 2 == 0:
                return -1
            vx, vy = -vy, vx

