def find_pocket(n, m, x, y, vx, vy):
    # Define the pocket coordinates
    pockets = [(0, 0), (n, 0), (0, m), (n, m)]

    # Check if the ball is already in a pocket
    for px, py in pockets:
        if x == px and y == py:
            return -1

    # Simulate the ball's movement
    while True:
        # Check if the ball has reached a pocket
        for px, py in pockets:
            if x == px and y == py:
                return px, py

        # Update the ball's position
        x += vx
        y += vy

        # Check for collisions with the table edges
        if x < 0:
            vx = -vx
            x = 0
        elif x > n:
            vx = -vx
            x = n
        if y < 0:
            vy = -vy
            y = 0
        elif y > m:
            vy = -vy
            y = m

        # If the ball is moving indefinitely, return -1
        if (vx, vy) == (0, 0):
            return -1

