def find_frame(n, m, screen):
    # Find the white pixels
    white_pixels = []
    for i in range(n):
        for j in range(m):
            if screen[i][j] == 'w':
                white_pixels.append((i, j))

    # If there are no white pixels, return -1
    if not white_pixels:
        return -1

    # Find the minimum bounding box
    min_x, min_y = float('inf'), float('inf')
    max_x, max_y = 0, 0
    for x, y in white_pixels:
        min_x = min(min_x, x)
        min_y = min(min_y, y)
        max_x = max(max_x, x)
        max_y = max(max_y, y)

    # Check if the bounding box is a valid frame
    frame_size = max(max_x - min_x + 1, max_y - min_y + 1)
    if frame_size == 1:
        return 1

    for i in range(min_x, max_x + 1):
        for j in range(min_y, max_y + 1):
            if (i, j) not in white_pixels and (i == min_x or i == max_x or j == min_y or j == max_y):
                break
        else:
            continue
        break
    else:
        return frame_size

# Read the input
n, m = map(int, input().split())
screen = [input() for _ in range(n)]

# Find the frame
frame_size = find_frame(n, m, screen)

# Print the output
if frame_size == -1:
    print(-1)
else:
    for i in range(n):
        for j in range(m):
            if (i, j) in white_pixels:
                if i in [min_x, max_x] or j in [min_y, max_y]:
                    print('+', end='')
                else:
                    print('w', end='')
            else:
                print('.', end='')
        print()

