n, m, r, k = map(int, input().split())

def fishing(x, y):
    if x + r - 1 > n or y + r - 1 > m:
        return 0
    return 1

def expected(x, y):
    if x + r - 1 > n or y + r - 1 > m:
        return 0
    return (fishing(x, y) + fishing(x + 1, y) + fishing(x, y + 1) + fishing(x + 1, y + 1)) / 4

ans = 0
for x in range(n - r + 1):
    for y in range(m - r + 1):
        ans += expected(x, y)

print(ans / (n * m))

def solve(n, m, r, k):
    if r > min(n, m):
        return 0
    if k > min(n*m, 10**5):
        return 0
    if r*r > k:
        return 0
    if r*r == k:
        return k
    if r*r < k:
        return (k - r*r) / (n - r + 1) / (m - r + 1)

n, m, r, k = map(int, input().split())
print(solve(n, m, r, k))

