def min_cells_to_paint_black(n, m, grid):
    black_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                black_cells.append((i, j))

    if not black_cells:
        return 1

    min_row, max_row, min_col, max_col = n, 0, m, 0
    for cell in black_cells:
        min_row = min(min_row, cell[0])
        max_row = max(max_row, cell[0])
        min_col = min(min_col, cell[1])
        max_col = max(max_col, cell[1])

    side = max(max_row - min_row + 1, max_col - min_col + 1)

    for i in range(min_row, min_row + side):
        for j in range(min_col, min_col + side):
            if i < 0 or i >= n or j < 0 or j >= m or grid[i][j] != 'B':
                return -1

    return side**2 - len(black_cells)

