from collections import defaultdict, deque

def is_acyclic(n, edges):
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    queue = deque([u for u in range(1, n + 1) if in_degree[u] == 0])
    visited = set()

    while queue:
        u = queue.popleft()
        visited.add(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return len(visited) == n

def can_make_acyclic(n, edges):
    for i in range(len(edges)):
        new_edges = edges[:i] + edges[i+1:]
        if is_acyclic(n, new_edges):
            return "YES"
    return "NO"

n, m = map(int, input().split())
edges = [tuple(map(int, input().split())) for _ in range(m)]
print(can_make_acyclic(n, edges))

