def min_cost(n, L, costs):
    dp = [float('inf')] * (L + 1)
    dp[0] = 0

    for i in range(1, L + 1):
        for j in range(n):
            if (1 << j) - 1 <= i:
                dp[i] = min(dp[i], dp[i - (1 << j) + 1] + costs[j])

    return dp[L]

