def is_lucky(n, ticket):
    # Initialize a dictionary to keep track of the segments
    segments = {}
    for i in range(n):
        segments[i] = []

    # Iterate through the digits of the ticket and find the segments
    for i in range(n):
        digit = ticket[i]
        if digit in segments:
            segments[digit].append(i)
        else:
            segments[digit] = [i]

    # Check if there are any non-overlapping segments with equal sum
    for segment in segments.values():
        if len(segment) > 1 and sum(segment) == sum(segment[1:]) :
            return "YES"
    return "NO"

