def factorize(X):
    i = 2
    factors = []
    while i * i <= X:
        if X % i:
            i += 1
        else:
            X //= i
            factors.append(i)
    if X > 1:
        factors.append(X)
    return factors

def find_min_pair(X):
    factors = factorize(X)
    min_power = [0] * len(factors)
    max_power = [0] * len(factors)

    for i, factor in enumerate(factors):
        max_power[i] = X // factor
