def find_longcat(x):
    max_power = 0
    while (1 << max_power) <= x:
        max_power += 1

    steps = 0
    operation_A = []
    while x != (1 << max_power) - 1:
        if steps % 2 == 1:
            # Operation A: XOR with 2^n - 1
            for n in range(max_power, 0, -1):
                if x & (1 << (n - 1)):
                    x ^= (1 << n) - 1
                    operation_A.append(n)
                    break
        else:
            # Operation B: Increment
            x += 1
        steps += 1
        if steps > 40:
            break

    return steps, operation_A


