def optimise_blacklist(blacklist, whitelist):
    blacklist_set = set()
    whitelist_set = set()

    # Convert subnets to ranges of addresses
    def subnet_to_range(subnet):
        if '/' in subnet:
            ip, bits = subnet.split('/')
            mask = (1 << (32 - int(bits))) - 1
            return (int(ip.replace('.', '')) & ~mask, int(ip.replace('.', '')) | mask)
        else:
            return (int(subnet.replace('.', '')), int(subnet.replace('.', '')) + 1)

    # Add addresses to sets
    for item in blacklist:
        sign, subnet = item[0], item[1:]
        if sign == '-':
            start, end = subnet_to_range(subnet)
            blacklist_set.update(range(start, end))
        else:
            whitelist_set.add(int(subnet.replace('.', '')))

    # Remove whitelist addresses from blacklist set
    blacklist_set -= whitelist_set

    # Convert blacklist set back to subnets
    optimised_blacklist = []
    for ip in sorted(blacklist_set):
        start = ip
        while start + 1 in blacklist_set:
            start += 1
        end = start
        while (end >> 8) == ((end + 1) >> 8):
            end += 1
        optimised_blacklist.append(f"{start >> 24}.{(start >> 16) & 255}.{(start >> 8) & 255}.{start & 255}/{32 - (end.bit_length() - 1)}")

