def beatLevel(n, m, grid):
    if n == 0 or m == 0:
        return -1
    if n == 1 and m == 1:
        return 3
    if n == 1:
        return 1
    if m == 1:
        return 1
    dp = [[0 for _ in range(m)] for _ in range(n)]
    dp[0][0] = grid[0][0]
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + 1 if grid[i][0] == 0 else 0
