def solve(n, m, grid):
    target = [[0] * m for _ in range(n)]
    moves = []

    # Copy target grid to check if we can achieve the target
    for i in range(n):
        for j in range(m):
            target[i][j] = grid[i][j]

    # Check if the given grid is solvable
    for i in range(n):
        row_sum = sum(grid[i])
        if row_sum != target[i].count(target[i][0]):
            return -1

    for j in range(m):
        col_sum = sum(row[j] for row in grid)
        if col_sum != target[0].count(target[0][0]):
            return -1

    # Calculate the minimum moves needed
    min_moves = 0
    for i in range(n):
        if max(grid[i]) == 0:
            min_moves += 1
            for j in range(m):
                grid[i][j] += 1

    for j in range(m):
        if max(row[j] for row in grid) == 0:
            min_moves += 1
            for i in range(n):
                grid[i][j] += 1

    # Generate the move sequence
    for i in range(n):
        if max(grid[i]) > 0:
            moves.append(f"row {i+1}")
            for j in range(m):
                grid[i][j] -= 1
                if grid[i][j] == target[i][j]:
