def bfs(start, end):
    queue = []
    queue.append(start)
    visited = set()
    visited.add(start)
    step = 0
    while queue:
        size = len(queue)
        for i in range(size):
            node = queue.pop(0)
            if node == end:
                return step
            for neighbor in get_neighbors(node):
                if neighbor not in visited:
                    queue.append(neighbor)
                    visited.add(neighbor)
        step += 1
    return -1

def get_neighbors(node):
    neighbors = []
    i, j = node
    if i + 1 <= n:
        neighbors.append((i + 1, j))
    if j + 1 <= n:
        neighbors.append((i, j + 1))
    return neighbors

def is_volcano(node):
    i, j = node
    for volcano in volcanoes:
        if volcano[0] == i and volcano[1] == j:
            return True
    return False

