def can_reach(start, end, visited, island):
    queue = [(start, False)]
    while queue:
        cur_pos, is_backtrack = queue.pop(0)
        if cur_pos == end:
            return True
        if visited[cur_pos[0]][cur_pos[1]] == False:
            visited[cur_pos[0]][cur_pos[1]] = True
            if island[cur_pos[0]][cur_pos[1]] == "." and not is_backtrack:
                queue.append((cur_pos[0] + 1, cur_pos[1]))  # down
                queue.append((cur_pos[0] - 1, cur_pos[1]))  # up
                queue.append((cur_pos[0], cur_pos[1] + 1))  # right
                queue.append((cur_pos[0], cur_pos[1] - 1))  # left
            elif island[cur_pos[0]][cur_pos[1]] == "." and is_backtrack:
                queue.append((cur_pos[0] + 1, cur_pos[1]))  # down
            else:
                return False
    return False

