def max_grade(n, t, grade):
    grade_parts = grade.split('.')
    integer_part = int(grade_parts[0])
    decimal_part = list(map(int, grade_parts[1]))

    # If we have enough time to round each digit, we can just round up the integer part
    if t >= n:
        return str(integer_part + 1) + '.' + ''.join(map(str, decimal_part))

    # Otherwise, we need to round the decimal part
    for i in range(n):
        if t <= 0:
            break
        if decimal_part[i] < 5:
            decimal_part[i] = 5
            t -= 1
        else:
            decimal_part[i] = 0
            if i + 1 < n:
                decimal_part[i + 1] = 1
            else:
                integer_part += 1
            t -= 1

    return str(integer_part) + '.' + ''.join(map(str, decimal_part))


