import math

def mod_inv(a, m):
    # Calculate the multiplicative inverse of a mod m
    # See https://en.wikipedia.org/wiki/Modular_multiplicative_inverse#Python
    return pow(a, m-2, m)

def extended_euclid(a, b):
    # Extended Euclidean algorithm
    # See https://en.wikipedia.org/wiki/Extended_Euclidean_algorithm#Python
    if a == 0:
        return (b, 0, 1)
    else:
        g, x, y = extended_euclid(b % a, a)
        return (g, y - (b // a) * x, x)

def crt(a, m, n):
    # Chinese Remainder Theorem
    # See https://en.wikipedia.org/wiki/Chinese_remainder_theorem#Python
    prod = m * n
    lcm = math.lcm(m, n)
    return (a * mod_inv(lcm // prod, lcm) % lcm) % prod

def solve(p, k):
    # Solve the equation f(k * x % p) = k * f(x) % p for x in [0, p - 1]
    # This can be done using the Extended Euclidean algorithm and the Chinese Remainder Theorem
    g, x, _ = extended_euclid(k, p)
    if g!= 1:
        return -1
    else:
        f = crt([x, p-x], m=p, n=p)
        return len(set([f(i) for i in range(p)])) % (10**9 + 7)

