def is_achievable(H, W, a):
    # Initialize a dictionary to keep track of the number of leaves in each row
    row_counts = {i: 0 for i in range(H)}

    # Initialize a dictionary to keep track of the number of leaves in each column
    col_counts = {j: 0 for j in range(W)}

    # Initialize a set to keep track of the leaves that need to be removed
    leaves_to_remove = set()

    # Iterate through each row and column
    for i in range(H):
        for j in range(W):
            # If the current square is empty, increment the row count
            if a[i * W + j] == ".":
                row_counts[i] += 1

            # If the current square contains the leaf S, increment the column count
            elif a[i * W + j] == "S":
                col_counts[j] += 1

            # If the current square contains the leaf T, increment the column count
            elif a[i * W + j] == "T":
                col_counts[j] += 1

            # If the current square contains a leaf that is not S or T, add it to the set of leaves to remove
            elif a[i * W + j] != "S" and a[i * W + j] != "T":
                leaves_to_remove.add(a[i * W + j])

    # If there are more than one leaf in each row or column, the objective is not achievable
    if any(row_counts.values()) > 1 or any(col_counts.values()) > 1:
        return -1

    # If there are no leaves to remove, the objective is achievable
    return len(leaves_to_remove)

