def max_chessmen(n, m):
    dp = [[0 for _ in range(m)] for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                dp[i][j] = 1
            elif i == 0 or j == 0:
                dp[i][j] = 1
            elif abs(i-j) == 3:
                dp[i][j] = dp[i-1][j-1] + 2
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[n-1][m-1]

