def place_chessmen(n, m, board):
    chessmen = 0
    while True:
        for i in range(n):
            for j in range(m):
                if board[i][j] == 0:
                    for dx, dy in [(1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2)]:
                        x, y = i, j
                        while is_valid(x, y, x+dx, y+dy, board):
                            x, y = x+dx, y+dy
                            chessmen += 1
                            board[x][y] = 1
                            if chessmen >= n*m:
                                return chessmen
                            break
                    board[i][j] = 1
                    chessmen += 1
                    if chessmen >= n*m:
                        return chessmen
    return chessmen

