import sys

n, m = map(int, input().split())

def is_similar(G, H):
    if len(G) != len(H):
        return False
    if len(G) == 2:
        return True
    for v in G:
        if v not in H:
            return False
    for v in H:
        if v not in G:
            return False
    for v in G:
        for u in G:
            if (u, v) in G and (u, v) not in H:
                return False
    for v in H:
        for u in H:
            if (u, v) in H and (u, v) not in G:
                return False
    return True

def is_min_cut(G, m):
    if len(G) == 2:
        return True
    if len(G) < m:
        return False
    for v in G:
        if len(G[v]) < m:
            return False
    return True

def count_worlds(n, m):
    if n == 0:
        return 1
    if m == 0:
        return 0
    count = 0
    for i in range(n):
        for j in range(i+1, n):
            G = {i: set(), j: set()}
            for k in range(i+1, j):
                G[i].add(k)
                G[j].add(k)
            if is_min_cut(G, m):
                count += count_worlds(n-2, m-1)
    return count

print(count_worlds(n, m))

