def find_empty_cells(maze):
    n = len(maze)
    m = len(maze[0])
    empty_cells = []
    for i in range(n):
        for j in range(m):
            if maze[i][j] == '.':
                empty_cells.append((i, j))
    return empty_cells

def dfs(maze, x, y, visited):
    n = len(maze)
    m = len(maze[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited[x][y] = True
    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and maze[nx][ny] == '.':
            dfs(maze, nx, ny, visited)

def solve_maze(maze, k):
    n = len(maze)
    m = len(maze[0])
    empty_cells = find_empty_cells(maze)
    for _ in range(k):
        visited = [[False] * m for _ in range(n)]
        dfs(maze, empty_cells[0][0], empty_cells[0][1], visited)
        for i, (x, y) in enumerate(empty_cells):
            if visited[x][y]:
                empty_cells.pop(i)
                maze[x][y] = 'X'
                break
    return maze

