def can_add_walls(i, j, visited, k):
    # Check if we have added enough walls
    if len([True for row in visited for wall in row if wall]) == k:
        return True

    # Check if we can add a wall at (i, j)
    if i >= 0 and j >= 0 and i < n and j < m and maze[i][j] == "." and not visited[i][j]:
        # Mark (i, j) as visited and add a wall
        visited[i][j] = True
        # Check if we can add more walls
        if can_add_walls(i-1, j, visited, k) or can_add_walls(i+1, j, visited, k) or can_add_walls(i, j-1, visited, k) or can_add_walls(i, j+1, visited, k):
            return True
        # Remove the wall and mark (i, j) as unvisited
        visited[i][j] = False
    return False

# Mark all cells as unvisited and add walls
