def construct_sequence(N, A, B):
    if A + B - 1 > N:
        return -1

    sequence = [0] * N
    increasing_indices = sorted(range(A), reverse=True)
    decreasing_indices = sorted(range(B), reverse=True)

    for i in range(N):
        if i in increasing_indices:
            sequence[i] = i + 1
            increasing_indices.remove(i)
        elif i in decreasing_indices:
            sequence[i] = N - decreasing_indices.index(i)
            decreasing_indices.remove(i)
        else:
            sequence[i] = i + 1

    return sequence


