def find_sequence(N, A, B):
    # Check if it's possible to have both A and B as lengths of subsequences
    if A + B > N + 1 or A * B < N:
        return -1

    # If A == B, we can simply alternate between increasing and decreasing sequences
    if A == B:
        seq = [i for i in range(1, N + 1)]
        seq[::2], seq[1::2] = seq[1::2], seq[::2]
        return ' '.join(map(str, seq))

    # If A > B, we need to create an increasing sequence of length A and then fill the rest with decreasing sequence of length B
    seq = [i for i in range(1, A + 1)]
    remaining = N - A
    for i in range(B - 1, 0, -1):
        seq.append(A + i)
        remaining -= 1
        if remaining >= i:
            seq.extend(range(A + i - 1, A - i, -1))
            remaining -= i

    # If there's any remaining space, fill it with the remaining numbers
    if remaining > 0:
        seq.extend(range(A, A - remaining, -1))

    return ' '.join(map(str, seq))

