    count_a = 0
    count_b = 0
    max_count = 0
    for i in range(n):
        if s[i] == 'a':
            count_a += 1
        elif s[i] == 'b' and t[i] == 'a':
            count_a += 1
        elif s[i] == 'b':
            count_b += 1

        if s[i] == t[i]:
            max_count += min(count_a, count_b)
