import math

def restore_cube(input_lines):
    # Read input
    points = []
    for line in input_lines:
        point = [int(x) for x in line.split()]
        points.append(point)

    # Check if there is a solution
    if not check_solution(points):
        return "NO"

    # Find the solution that minimizes the Manhattan distance
    distances = []
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            distances.append(manhattan_distance(points[i], points[j]))
    min_distance = min(distances)
    min_distance_indices = [i for i, d in enumerate(distances) if d == min_distance]

    # Restore the points with the minimum Manhattan distance
    restored_points = []
    for index in min_distance_indices:
        restored_points.append(points[index])

    # Print the restored points
    for point in restored_points:
        print(*point)
    return "YES"

def check_solution(points):
    # Check if the points form a cube
    if not check_cube(points):
        return False

    # Check if the points have integer coordinates
    for point in points:
        if any(x % 1!= 0 for x in point):
            return False

    # Check if the points are distinct
    point_set = set()
    for point in points:
        if point in point_set:
            return False
        point_set.add(point)

    return True

def check_cube(points):
    # Check if the points form a square
    side_length = math.sqrt(sum((point[0] - point[1]) ** 2 for point in points))
    if side_length!= int(side_length):
        return False

    # Check if the points form a rhombus
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            if points[i][1] == points[j][1] or points[i][0] == points[j][0]:
                return False

    return True

def manhattan_distance(point1, point2):
    return sum(abs(x1 - x2) for x1, x2 in zip(point1, point2))

# Read input from Standard Input
input_lines = input().splitlines()

# Call the function to restore the cube
result = restore_cube(input_lines)

# Print the result
print(result)

