    # we look for the maximum pile size and count how many divisors have that size
    max_pile_size = max(piles_per_divisor)
    result = sum(piles_per_divisor.count(max_pile_size) for _ in range(3))

    # Output the result modulo 10^9 + 7
    print(result % (10**9 + 7))

