from collections import defaultdict

def solve():
    N = int(input())
    P = list(map(int, input().split()))
    X = list(map(int, input().split()))
    G = defaultdict(list)
    for i, p in enumerate(P, 2):
        G[p-1].append(i-1)
    dp = [[0]*(X[0]+1) for _ in range(N+1)]
    dp[0][0] = 1
    for v in range(N-1, -1, -1):
        dp2 = [[0]*(X[v]+1) for _ in range(len(G[v])+1)]
        dp2[0][0] = 1
        for i, c in enumerate(G[v], 1):
            for j in range(X[v]+1):
