                if j >= dp[c][X[c]]:
                    dp2[i][j] |= dp2[i-1][j-dp[c][X[c]]]
        dp[v] = dp2[-1]
    print("POSSIBLE" if dp[0][X[0]] else "IMPOSSIBLE")

