def count_distinct_integers(n):
    # Initialize counts for each possible value from 1 to n
    counts = [0] * (n + 1)

    # Base cases: I, V, X, L contribute 1, 5, 10, 50 to the total value
    counts[1], counts[5], counts[10], counts[50] = 1, 1, 1, 1

    # Iterate through possible values up to n
    for i in range(6, n + 1):
        # Add counts for subtracting smaller values from i
        if i >= 5:
            counts[i] += counts[i - 5]
        if i >= 10:
            counts[i] += counts[i - 10]
        if i >= 50:
            counts[i] += counts[i - 50]
        # Add count for adding smaller values to i
        if i >= 1:
            counts[i] += counts[i - 1]
        if i >= 10 and i != 11:
            counts[i] += counts[i - 10]
        if i >= 50 and i != 55:
            counts[i] += counts[i - 50]

    return counts[n]

