import sys

def dfs(graph, start, visited):
    visited.add(start)
    for node in graph[start]:
        if node not in visited:
            dfs(graph, node, visited)

def get_paths(graph, start, end):
    visited = set()
    dfs(graph, start, visited)
    paths = []
    for node in visited:
        if node == end:
            paths.append(node)
        else:
            paths.append(node)
    return paths

def get_path_length(graph, paths, start, end):
    path_length = 0
    for path in paths:
        if start in path and end in path:
            path_length += 1
    return path_length

def get_max_path_length(graph, start, end):
    paths = get_paths(graph, start, end)
    return get_path_length(graph, paths, start, end)

def get_max_path_length_between_all_pairs(graph):
    max_path_length = 0
    for node1 in graph:
        for node2 in graph:
            if node1 != node2:
                max_path_length = max(max_path_length, get_max_path_length(graph, node1, node2))
    return max_path_length

