    divisors.sort()
    x = divisors[0]
    y = divisors[1]
    for i in range(2, n):
        if divisors[i] == divisors[i-1]:
            if divisors[i] == x:
                x *= divisors[i+1]
            else:
                y *= divisors[i+1]
        else:
            if divisors[i] == x:
                x *= divisors[i-1]
            else:
                y *= divisors[i-1]
    return x, y

