# Create a list to keep track of who has not received a gift yet
not_received = [0] * (n + 1)

# Assign gifts to friends who already know whom they want to give to
for i in range(n):
    if f[i] != 0:
        f[f[i] - 1] = i + 1  # The recipient is assigned the giver's index + 1
        not_received[i + 1] = 1  # Mark the giver as having received a gift

# Assign remaining gifts to friends who don't know whom they want to give to
for i in range(n):
    if f[i] == 0 and not_received[i + 1] == 0:
        # Find the first person who hasn't received a gift yet
        for j in range(i + 1, n + 1):
            if not_received[j] == 0:
                f[i] = j  # Assign the recipient's index + 1
                not_received[j] = 1  # Mark the recipient as having received a gift
                break

# Print the result
print(*f)

