    results = []
    for i in range(t):
        a, b, c = test_cases[i]
        res = 0
        while b % a != 0 or c % b != 0:
            if b % a == 0:
                res += 1
            b += 1
            if b > c:
                b = c
                c += 1
        results.append((res, b, c))
    return results

