from collections import defaultdict

def solve_exams(n, m, exams):
    # Create a dictionary to store the preparation and exam days for each exam
    exam_days = defaultdict(list)
    for i, (s, d, c) in enumerate(exams):
        for j in range(s, d):
            exam_days[i+1].append(j)
        exam_days[i+1].append(d)

    # Create a schedule for Petya
    schedule = [0] * n
    for i in range(n):
        # Check if the current day is an exam day
        exam_day = False
        for exam, days in exam_days.items():
            if i in days:
                schedule[i] = exam
                exam_day = True
                break

        # If the current day is not an exam day, check if Petya can prepare for an exam
