def count_moves(n, m):
    if m % n != 0:
        return -1

    gcd = math.gcd(n, m)
    if gcd != 1:
        return -1

    n //= gcd
    m //= gcd

    moves_to_m = 0
    while n != m:
        if n < m:
            n *= 2
        else:
            n *= 3
        moves_to_m += 1

    return moves_to_m

