from collections import defaultdict

def find_spanning_tree(n, m, D, edges):
    # Create an adjacency list to represent the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Initialize the visited set and the spanning tree
    visited = set()
    spanning_tree = []

    # Perform a depth-first search (DFS) to find a spanning tree
    def dfs(node, parent, degree):
        visited.add(node)
        if node == 1 and degree == D:
            return True
        for neighbor in graph[node]:
            if neighbor != parent:
                if dfs(neighbor, node, degree + 1):
                    spanning_tree.append((node, neighbor))
                    return True
        return False

    # Start the DFS from the first vertex
    if dfs(1, -1, 0):
        print("YES")
        for u, v in spanning_tree:
            print(u, v)
    else:
        print("NO")

# Read the input
n, m, D = map(int, input().split())
edges = [tuple(map(int, input().split())) for _ in range(m)]

# Solve the problem
find_spanning_tree(n, m, D, edges)

