def can_complete_wall(n, heights):
    # Check if the wall is already complete
    if len(set(heights)) == 1:
        return "YES"

    # Check if the wall can be made complete by making all heights equal
    min_height = min(heights)
    max_height = max(heights)
    if max_height - min_height <= 0:
        return "YES"

    # Check if there are consecutive parts with the same height that can be joined
    for i in range(1, n):
        if heights[i] == heights[i - 1]:
            target_height = (max_height + min_height) // 2
            if heights[i] == target_height:
                return "YES"
            else:
                # Try to join this pair and check if the remaining parts can be made equal
                new_heights = heights[:i] + [target_height] + heights[i + 1:]
                if can_join_remaining(new_heights, target_height):
                    return "YES"

    return "NO"

def can_join_remaining(heights, target_height):
    n = len(heights)
    i = 0
    while i < n - 1:
        if heights[i] == target_height and heights[i + 1] == target_height:
            heights = heights[:i] + heights[i + 2:]
            n -= 1
        else:
            i += 1
    return len(heights) == 1 or can_join_remaining(heights, target_height)

