def count_regular_bracket_sequences(n, s):
    # Initialize a hash table to count the number of regular bracket sequences
    # of length 2n containing the given bracket sequence s as a substring
    count = { }
    for i in range(2**n):
        current = ""
        j = 0
        while j < n:
            current += s[j]
            j += 1
        count[current] = count.get(current, 0) + 1
    return count.get(s, 0) % (10**9 + 7)

