    n = len(matrix)
    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[n-i-1][n-j-1]:
                return False
    return True

def solve(matrix, nums, i, j):
    n = len(matrix)
    if i == n:
        return is_palindromic(matrix)
    if j == n:
        return solve(matrix, nums, i+1, 0)
    for k in range(len(nums)):
        if nums[k] is not None:
            matrix[i][j] = nums[k]
            nums[k] = None
            if solve(matrix, nums, i, j+1):
                return True
            nums[k] = matrix[i][j]
            matrix[i][j] = None
    return False

