def main():
    n, d, k = map(int, input().split())

    if d > 2 * (n - 1) or (d == 1 and n > 2) or (d == 2 and n > 3 and k < 3):
        print("NO")
        return

    # First, we try to create a tree with diameter d-1 by connecting a central node to all others
    # Then, we add a path of length 2 to increase the diameter to d
    if d == 1:
        if n == 2:
            print("YES")
            print("1 2")
        else:
            print("NO")
        return

    # Create a star-like tree with a center node (degree k) and k leaf nodes
    center = 1
    leaves = list(range(2, n + 1))
    for _ in range(k - 1):
        print(f"{center} {leaves.pop()}")

    # Connect the remaining leaf nodes to form a path of length d - k - 1
    path_length = d - k - 1
    if path_length > 0:
        current = center
        for _ in range(path_length // 2):
            next_leaf = leaves.pop()
            print(f"{current} {next_leaf}")
            current = next_leaf
        if path_length % 2 == 1:
            last_leaf = leaves.pop()
            print(f"{current} {last_leaf}")

    # Connect the last leaf to the center to complete the diameter
    if path_length % 2 == 1:
        print(f"{last_leaf} {center}")

    print("YES")

