            if i + r - 1 < n and a[i + r - 1]:
                # If the position can be warmed up, update the number of heaters used for that position
                used_heaters[i + r - 1] += 1
            # Otherwise, check if there is a heater in the next position that can warm up the current position
            elif i + r < n and a[i + r]:
                used_heaters[i + r] += 1

    # Return the minimum number of heaters used
    return min(used_heaters.values())

