def count_ways(broken_steps, N, M):
    if N == 0:
        return 1
    if N in broken_steps:
        return 0
    if N - 1 in broken_steps:
        return count_ways(broken_steps, N - 1, M)
    if N - 2 in broken_steps:
        return count_ways(broken_steps, N - 2, M)
    return count_ways(broken_steps, N - 1, M) + count_ways(broken_steps, N - 2, M)


