import sys

def find_string(s, b):
    n = len(s)
    # create a set of all possible characters
    char_set = set(chr(i) for i in range(ord('a'), ord('z') + 1))
    # remove characters that cannot appear in the string
    char_set -= set(s)
    # create a dictionary that maps each character to a list of possible positions
    char_pos = {c: list(range(n)) for c in char_set}
    # for each character, remove all positions that cannot contain it
    for c in char_set:
        char_pos[c] = [pos for pos in char_pos[c] if s[pos] < c]
    # for each position, remove all characters that cannot appear there
    for i in range(n):
        char_set -= set(s[j] for j in char_pos[s[i]] if j!= i)
    # find the longest possible string that contains all characters
    best_len = 0
    best_str = ''
    for c in char_set:
        new_str = c
        for pos in char_pos[c]:
            new_str += s[pos]
            if len(new_str) > best_len:
                best_len = len(new_str)
                best_str = new_str
    # check if the positions in b match the positions in the best string
    if b == [0] * n:
        return best_str
    else:
        matches = True
        for i in range(n):
            if b[i]!= len(set(best_str[j] for j in range(i) if j not in char_pos[best_str[i]])):
                matches = False
                break
        if matches:
            return best_str
