    words_len = [len(word) for word in words]
    segments = {}
    prefix_len = 0

    for i in range(n):
        current_prefix = words[i][:prefix_len]
        if current_prefix in segments:
            segments[current_prefix].append(i)
        else:
            segments[current_prefix] = [i]

        if i > 0 and words[i] == words[i - 1]:
            prefix_len += 1
        else:
