                # If the team with the largest skill difference is not empty and the difference between the skill of the last student in the first team and the skill of the current student is within 5
                if first_team and abs(a[first_team[-1]] - a[i]) <= 5:
                    first_team.add(i)
    # Return the total number of students in the balanced teams
    return len(first_team)

