def sort_matrix(a):
    n, m = len(a), len(a[0])
    row_ops = [0] * n
    col_ops = [0] * m

    for i in range(n):
        for j in range(m):
            if a[i][j] and not any(a[i][k] or not a[i][k] == a[i][j] for k in range(m)):
                row_ops[i] = 1
                break
            if a[k][j] and not any(a[k][l] or not a[k][l] == a[i][j] for l in range(n)):
                col_ops[j] = 1
                break

    if any(a[i][j] and (row_ops[i] != (not a[i][j]) or col_ops[j] != (not a[i][j])) for i in range(n) for j in range(m)):
        return "NO"

    res_rows = ["0"] * n
    res_cols = ["0"] * m

    for i in range(n):
        res_rows[i] = str(row_ops[i])

    for j in range(m):
        res_cols[j] = str(col_ops[j])

    return "YES\n" + "\n".join(res_rows) + "\n" + "\n".join(res_cols)

